using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Common.Exceptions;using OAS.Contracts.Accounting.ExchangeRates;using OAS.Domain.Accounting.Entities;using ContractRateType=OAS.Contracts.Accounting.Enums.ExchangeRateType;
namespace OAS.Application.Accounting.ExchangeRates.Queries.GetExchangeRateById;public sealed class GetExchangeRateByIdQueryHandler(IReadRepository<ExchangeRate,Guid> repository,IReadRepository<Currency,Guid> currencies):IRequestHandler<GetExchangeRateByIdQuery,ExchangeRateDto>{public async Task<ExchangeRateDto> Handle(GetExchangeRateByIdQuery r,CancellationToken ct){var e=await repository.GetByIdAsync(r.Id,ct)??throw new NotFoundException(nameof(ExchangeRate),r.Id);var c=await currencies.GetByIdAsync(e.CurrencyId,ct)??throw new NotFoundException(nameof(Currency),e.CurrencyId);return new(e.Id,e.CurrencyId,c.Code,e.RateDate,e.Rate,(ContractRateType)(byte)e.RateType,e.IsActive,Convert.ToBase64String(e.RowVersion));}}
